  function fitPhone() {
    const mobile = window.matchMedia('(max-width:520px)').matches;
    if (mobile) {
      const vv = window.visualViewport;
      const viewportWidth = Math.max(1, vv ? vv.width : window.innerWidth);
      const viewportHeight = Math.max(1, vv ? vv.height : window.innerHeight);
      const viewportLeft = vv ? vv.offsetLeft : 0;
      const viewportTop = vv ? vv.offsetTop : 0;

      // Fill the Safari content width exactly. Instead of shrinking the entire
      // 393×852 mockup, give the interface a shorter live canvas and let all
      // bottom-anchored controls move upward. Icons therefore keep their shape.
      const scale = viewportWidth / 393;
      const uiHeight = viewportHeight / scale;

      shell.style.setProperty('--mobile-scale', String(scale));
      shell.style.setProperty('--mobile-ui-h', `${uiHeight}px`);
      shell.style.left = `${viewportLeft}px`;
      shell.style.top = `${viewportTop}px`;
      shell.style.transform = '';
      return;
    }

    shell.style.removeProperty('--mobile-scale');
    shell.style.removeProperty('--mobile-ui-h');
    shell.style.left = '';
    shell.style.top = '';
    const s = Math.min((window.innerWidth - 36) / 411, (window.innerHeight - 36) / 870, 1);
    shell.style.transform = `scale(${s})`;
  }

