  function scrollPhotosToLatest() {
    const scroll = appLayer.querySelector('#photosScroll');
    if (!scroll) return;
    const latestPhoto = photoItems[photoItems.length - 1];
    const latest = latestPhoto
      ? scroll.querySelector(`[data-photo-index="${latestPhoto.number}"]`)
      : null;
    const moveToLatest = () => {
      if (!latest) {
        scroll.scrollTop = scroll.scrollHeight;
        return;
      }
      const scrollRect = scroll.getBoundingClientRect();
      const latestRect = latest.getBoundingClientRect();
      scroll.scrollTop += latestRect.bottom - scrollRect.bottom + 96;
    };
    moveToLatest();
    const images = [...scroll.querySelectorAll('img')];
    Promise.all(images.map(img => {
      if (img.complete) return Promise.resolve();
      return new Promise(resolve => {
        img.addEventListener('load', resolve, {once:true});
        img.addEventListener('error', resolve, {once:true});
      });
    })).then(() => requestAnimationFrame(moveToLatest));
  }

